// Package public carries the files a browser requests by a fixed name at the
// site root: the icons, the social preview image and the web app manifest.
// robots.txt is generated by cmd/timlee-web, because it has to name the
// sitemap by the deployment's own origin.
//
// They are not content-hashed, so they cannot be cached forever the way the
// built assets are; cmd/timlee-web serves them with a short max-age and a
// validator instead. Embedding them keeps the release binary the only
// artefact that ships.
package public

import "embed"

//go:embed *.svg *.png *.webmanifest
var files embed.FS

// FS returns the embedded tree.
func FS() embed.FS { return files }
